from contextlib import closing
from pathlib import Path
import json
import sqlite3
import sys
import tempfile
import vault

print(json.dumps({'python': sys.version.split()[0], 'sqlite': sqlite3.sqlite_version}))

def snapshot(path):
    with closing(sqlite3.connect(path)) as con:
        return {table: con.execute('SELECT * FROM ' + table + ' ORDER BY rowid').fetchall()
                for table in ('accounts', 'transfers', 'audit')}

cases = {
    'ignored_conflict_control': '''
        CREATE UNIQUE INDEX unique_balance ON accounts(balance);
        CREATE TRIGGER audit_side_effect AFTER INSERT ON audit BEGIN
            INSERT OR IGNORE INTO accounts VALUES ('red','replacement',77);
        END;
    ''',
    'replacement_deletes_foreign_account': '''
        CREATE UNIQUE INDEX unique_balance ON accounts(balance);
        CREATE TRIGGER audit_side_effect AFTER INSERT ON audit BEGIN
            INSERT OR REPLACE INTO accounts VALUES ('red','replacement',77);
        END;
    ''',
    'credit_reverted': '''
        CREATE TRIGGER audit_side_effect AFTER INSERT ON audit BEGIN
            UPDATE accounts SET balance=balance-NEW.amount
            WHERE tenant=NEW.tenant AND name=NEW.target;
        END;
    ''',
    'duplicate_audit': '''
        CREATE TRIGGER audit_side_effect AFTER INSERT ON audit BEGIN
            INSERT INTO audit VALUES (NEW.tenant,NEW.key,NEW.source,NEW.target,NEW.amount);
        END;
    ''',
    'history_removed': '''
        CREATE TRIGGER audit_side_effect AFTER INSERT ON audit BEGIN
            DELETE FROM transfers WHERE tenant='blue' AND key='historic';
            DELETE FROM audit WHERE tenant='blue' AND key='historic';
        END;
    ''',
}
with tempfile.TemporaryDirectory(dir=Path.cwd(), prefix='assessment-') as tmp:
    for name, ddl in cases.items():
        path = Path(tmp) / (name + '.sqlite')
        vault.init_db(path)
        with closing(sqlite3.connect(path)) as con, con:
            con.executemany('INSERT INTO accounts VALUES (?,?,?)',
                            [('red','a',100), ('red','b',20), ('blue','private',77)])
            for table in ('transfers', 'audit'):
                con.execute('INSERT INTO ' + table + ' VALUES (?,?,?,?,?)',
                            ('blue', 'historic', 'private', 'b', 2))
            con.executescript(ddl)
        before = snapshot(path)
        try:
            result = vault.transfer(path, 'red', 'a', 'b', 10, 'new')
            outcome = {'receipt': result}
        except Exception as exc:
            outcome = {'exception': type(exc).__name__, 'message': str(exc)}
        after = snapshot(path)
        expected = {table: list(rows) for table, rows in before.items()}
        expected['accounts'][0:2] = [('red','a',90), ('red','b',30)]
        for table in ('transfers', 'audit'):
            expected[table].append(('red','new','a','b',10))
        with closing(sqlite3.connect(path)) as con:
            preserved_trigger = con.execute(\"SELECT count(*) FROM sqlite_master WHERE type='trigger'\").fetchone()[0]
        print(json.dumps({'case': name, **outcome, 'matches_required_delta': after == expected,
                          'accounts_after_reopen': after['accounts'],
                          'transfers_after_reopen': after['transfers'],
                          'audit_after_reopen': after['audit'],
                          'triggers_remaining': preserved_trigger}))
PY"

